// Renders a self-contained bash script that connects to a channel
// from a remote shell with zero install (just curl + jq).

export function renderJoinScript({ bakedUrl }) {
  // If bakedUrl is set, the script uses it. If null, the script requires
  // URL as $1.
  const urlBlock = bakedUrl
    ? `URL="\${1:-${bakedUrl}}"`
    : `URL="\${1:-}"
if [ -z "$URL" ]; then echo "usage: bash $0 <channel-url> [name]" >&2; exit 2; fi`

  return `#!/usr/bin/env bash
# agent-socket channel join — terminal client for an agent-socket channel.
# Generated by the host process; serves over the relay.
# Deps: bash, curl, jq.
#
# Recommended invocation:
#
#   bash <(curl -s URL/join.sh | jq -r .script) "" "<your-name>"
#
# Process substitution keeps your stdin = your terminal. The simpler-looking
# \`curl ... | bash\` doesn't work: bash uses stdin to read the script body,
# leaving the interactive read loop with no input source.

set -uo pipefail

# Channel URL (baked at serve time; can be overridden with $1).
${urlBlock}
URL="\${URL%/agents.md}"
URL="\${URL%/}"

# Name: $2, or $NAME env, or prompt.
NAME="\${2:-\${NAME:-}}"
if [ -z "\${NAME}" ]; then
  printf "Your name: "
  read NAME
fi
if [ -z "\${NAME}" ]; then echo "name is required" >&2; exit 2; fi

# Require jq.
if ! command -v jq >/dev/null 2>&1; then
  echo "this client needs 'jq'. install:" >&2
  echo "  macOS:        brew install jq" >&2
  echo "  Debian/Ubuntu: sudo apt install jq" >&2
  echo "  Alpine:       sudo apk add jq" >&2
  exit 2
fi

# Sanity check the URL.
if ! curl -s -f -o /dev/null "$URL/agents.md"; then
  echo "could not reach $URL/agents.md — check the URL or that the host is up." >&2
  exit 1
fi

printf "\\n  Joined as \\"%s\\".\\n" "$NAME"
echo  "  Type to send. Asterisk (*name) means the sender is waiting — answer promptly."
echo  "  Ctrl-C to leave."
printf "\\n"

SINCE_FILE="\$(mktemp -t as-channel-since-XXXXXX)"
echo 0 > "$SINCE_FILE"

cleanup() {
  [ -n "\${POLL_PID:-}" ] && kill "$POLL_PID" 2>/dev/null
  rm -f "$SINCE_FILE"
  exit 0
}
trap cleanup INT TERM EXIT

# Background poll loop.
(
  while :; do
    SINCE=\$(cat "$SINCE_FILE" 2>/dev/null || echo 0)
    if [ "$SINCE" = "0" ]; then
      body=\$(jq -n --arg n "$NAME" '{name:$n, wait:25}')
    else
      body=\$(jq -n --arg n "$NAME" --argjson s "$SINCE" '{name:$n, since:$s, wait:25}')
    fi
    resp=\$(curl -s -X POST -H 'content-type: application/json' -d "$body" "$URL/recv") || { sleep 3; continue; }
    latest=\$(echo "$resp" | jq -r '.latest_seq // empty')
    [ -n "$latest" ] && echo "$latest" > "$SINCE_FILE"
    echo "$resp" | jq -r '.messages[]? | "[\\(if .awaiting then "*" else " " end)\\(.from)] \\(.text)"'
    missed=\$(echo "$resp" | jq -r '.missed_messages // empty')
    if [ -n "$missed" ] && [ "$missed" -gt 0 ]; then
      echo "# skipped $missed older messages (host's retention window exceeded)"
    fi
  done
) &
POLL_PID=$!

# Foreground stdin reader.
while IFS= read -r line; do
  [ -z "$line" ] && continue
  body=\$(jq -n --arg n "$NAME" --arg t "$line" '{name:$n, text:$t}')
  curl -s -X POST -H 'content-type: application/json' -d "$body" "$URL/send" >/dev/null || \\
    echo "! send failed" >&2
done

cleanup
`
}
